From bd76b353284aaa0d5be4e06d4ccff6aeee7bb65a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:07:22 +0100
Subject: [PATCH] applets/taskmanager: don't keep panel shown after group popup
 closes

The group popup saved the applet status on opening and wrote it back on
closing, so attention cleared from the popup came back and kept auto
hide panels shown. The status binding now keeps them shown while open.

BUG: 511950
---
 applets/taskmanager/qml/GroupDialog.qml | 6 ------
 applets/taskmanager/qml/main.qml        | 5 +++--
 2 files changed, 3 insertions(+), 8 deletions(-)

diff --git a/applets/taskmanager/qml/GroupDialog.qml b/applets/taskmanager/qml/GroupDialog.qml
index 8866a24ed9..e073353db3 100644
--- a/applets/taskmanager/qml/GroupDialog.qml
+++ b/applets/taskmanager/qml/GroupDialog.qml
@@ -61,8 +61,6 @@ PlasmaCore.PopupPlasmaWindow {
     readonly property real preferredHeight: Screen.height / 2
     readonly property real contentWidth: mainItem.width // No padding here to avoid text elide.

-    property /*PlasmaCore.ItemStatus*/int _oldAppletStatus: PlasmaCore.Types.UnknownStatus
-
     function findActiveTaskIndex(): void {
         if (!tasksModel.activeTask) {
             return;
@@ -204,14 +202,10 @@ PlasmaCore.PopupPlasmaWindow {

     onVisibleChanged: {
         if (visible) {
-            _oldAppletStatus = Plasmoid.status;
-            Plasmoid.status = PlasmaCore.Types.RequiresAttentionStatus;
-
             groupDialog.requestActivate();
             groupListView.forceActiveFocus(); // Active focus on ListView so keyboard navigation can work.
             Qt.callLater(findActiveTaskIndex);
         } else {
-            Plasmoid.status = _oldAppletStatus;
             tasks.groupDialog = null;
             destroy();
         }
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..8674dfd2c6 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -353,8 +353,9 @@ PlasmoidItem {
         Binding {
             target: Plasmoid
             property: "status"
-            value: (tasksModel.anyTaskDemandsAttention && Plasmoid.configuration.unhideOnAttention
-                ? PlasmaCore.Types.NeedsAttentionStatus : PlasmaCore.Types.PassiveStatus)
+            value: tasks.groupDialog?.visible ? PlasmaCore.Types.RequiresAttentionStatus
+                : (tasksModel.anyTaskDemandsAttention && Plasmoid.configuration.unhideOnAttention
+                    ? PlasmaCore.Types.NeedsAttentionStatus : PlasmaCore.Types.PassiveStatus)
             restoreMode: Binding.RestoreBinding
         }

